operation.add:
if ($this->config->get('websky_lightning_status') && !headers_sent() && !empty($output) && stripos($output, '<html') !== false && empty($_SERVER['HTTP_X_REQUESTED_WITH']) && empty($_COOKIE)) {
    $output = preg_replace('/<!--[\\s\\S]*?-->/', '', $output);
    $output = preg_replace('/[\\t ]+/', ' ', $output);
    $output = preg_replace('/>\\s+</', '><', $output);
}
